import java.io.*;
import java.util.*;

public class Main {

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buf = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buf);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buf[ptr++] & 0xFF;
        }

        int nextInt() throws IOException {
            int c = read();
            while (c != -1 && c <= ' ') c = read();
            if (c == -1) return -1;
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c != -1 && c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }

    static int oddManacher(int[] arr, int n) {
        int[] d = new int[n];
        int l = 0, r = -1;
        int ans = 0;

        for (int i = 0; i < n; i++) {
            int k = (i > r) ? 1 : Math.min(d[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && arr[i - k] == arr[i + k]) {
                k++;
            }
            d[i] = k;
            ans = Math.max(ans, k);
            if (i + k - 1 > r) {
                l = i - k + 1;
                r = i + k - 1;
            }
        }
        return ans;
    }

    static int solveOne(int n, int[] a) {
        int[] stack = new int[n];
        int top = 0;
        for (int x : a) {
            if (top > 0 && stack[top - 1] == x) {
                top--;
            } else {
                stack[top++] = x;
            }
        }

        int m = top;
        int base = (n - m) / 2;

        if (m == 0) return base;

        int[] reduced = Arrays.copyOf(stack, m);
        int extra = oddManacher(reduced, m);
        return base + extra;
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        StringBuilder sb = new StringBuilder();
        int T = fs.nextInt();
        for (int tc = 0; tc < T; tc++) {
            int n = fs.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = fs.nextInt();
            }
            sb.append(solveOne(n, a)).append('\n');
        }
        System.out.print(sb);
    }
}
