#include <bits/stdc++.h>
using namespace std;

// 求整数数组 arr 的最长奇回文半径（半径 = 从中心向一侧的长度，含中心）
int oddManacher(const vector<int>& arr) {
    int n = arr.size();
    vector<int> d(n);
    int l = 0, r = -1;
    int ans = 0;

    for (int i = 0; i < n; ++i) {
        int k = (i > r) ? 1 : min(d[l + r - i], r - i + 1);
        while (i - k >= 0 && i + k < n && arr[i - k] == arr[i + k]) {
            ++k;
        }
        d[i] = k;
        ans = max(ans, k);
        if (i + k - 1 > r) {
            l = i - k + 1;
            r = i + k - 1;
        }
    }
    return ans;
}

int solveOne(int n, const vector<int>& a) {
    vector<int> st;
    for (int x : a) {
        if (!st.empty() && st.back() == x) {
            st.pop_back();
        } else {
            st.push_back(x);
        }
    }

    int m = st.size();
    int base = (n - m) / 2;   // 不插入时的删除次数

    if (m == 0) return base;  // 已完全消除，插入无额外收益

    int extra = oddManacher(st);
    return base + extra;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

